"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { useRef } from "react";
import styled from "styled-components";
import { Flex, Text, useMedia, useSporeColors } from "ui/src";
const StyledInput = styled.input`
  text-align: right;
  padding: 12px 0;
  background-color: transparent;
  border: none;
  outline: none;
  font-size: 28px;
  @media (max-width: 768px) {
    font-size: 20px;
    padding: 8px 0;
  }
`;
export default function AmountInput({ value, onValueChange, error, userBalance }) {
  const inputRef = useRef(null);
  const media = useMedia();
  const colors = useSporeColors();
  const handleChange = (text) => {
    let numericValue = text.replace(/[^0-9.]/g, "");
    const decimals = numericValue.split(".");
    if (decimals.length > 2) {
      numericValue = decimals[0] + "." + decimals.slice(1).join("");
    }
    onValueChange(numericValue);
  };
  return <Flex>
      <Flex
    row
    mt={"$gap24"}
    px="$spacing16"
    py="$spacing16"
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    gap={"$gap12"}
    borderRadius={"$rounded12"}
    tabIndex={0}
    onPress={() => inputRef.current?.focus()}
    cursor="ibeam"
    focusWithinStyle={{ borderColor: "$neutral2" }}
    transition="border-color 0.3s ease"
    $md={{
      px: "$spacing12",
      py: "$spacing4",
      mt: "$gap12"
    }}
  >
        <Flex
    backgroundColor={"$slate"}
    py={"$padding16"}
    px={"$padding20"}
    borderRadius={"$rounded12"}
    row
    gap={"$gap8"}
    alignItems="center"
    borderWidth={1}
    borderColor={"$surface3"}
    $md={{ py: "$padding12", px: "$padding12", gap: "$gap4" }}
  >
          <LogoProvider size={media.md ? 16 : 20} />
          <Text variant={media.md ? "buttonLabel3" : "buttonLabel2"}>ABX</Text>
        </Flex>
        <Flex flexDirection="column" gap={"$gap8"} flex={1}>
          <StyledInput
    ref={inputRef}
    onChange={(e) => handleChange(e.target.value)}
    type="text"
    value={value}
    style={{ color: colors.neutral1.val }}
    autoFocus
  />
          <Text variant="body3" color={"$neutral3"} textAlign="right">
            ~$0
          </Text>
        </Flex>
      </Flex>
      <Flex row justifyContent="space-between" alignItems="center" mt={"$spacing6"}>
        {
    /* Removed error display - errors are now handled by button text */
  }
      </Flex>
    </Flex>;
}
