"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
import { fetchFromSubgraph } from "uniswap/src/utils/fetchSubgraph";
const GET_USER_LOCKS_QUERY = `
  query GetUserLocks($owner: String!) {
    veABXLocks(
      where: { owner: $owner }
      orderBy: lockStart
      orderDirection: desc
    ) {
      id
      owner
      amount
      lockEnd
      lockStart
      votingPower
      permanent
      managed
    }
  }
`;
const GET_MANAGED_RELAYS_QUERY = `
  query GetManagedRelays {
    veABXLocks(
      where: { managed: true }
      orderBy: updatedAtTimestamp
      orderDirection: desc
    ) {
      id
      owner
      amount
      lockEnd
      lockStart
      votingPower
      permanent
      managed
    }
  }
`;
const GET_VEABX_GLOBALS_QUERY = `
  query GetVeABXGlobals {
    veABXGlobals {
      id
      totalSupply
      totalPermanentLocked
    }
  }
`;
const GET_SINGLE_LOCK_QUERY = `
  query GetVeABXLock($id: String!) {
    veABXLock(id: $id) {
      id
      owner
      amount
      lockEnd
      lockStart
      votingPower
      permanent
      managed
    }
  }
`;
async function fetchDataFromSubgraph(query, variables = {}, chainId = UniverseChainId.Mainnet) {
  try {
    const subgraphs = getAbstractSubgraphs(chainId);
    const veabxSubgraph = subgraphs.veabx;
    console.log("fetchDataFromSubgraph - URL:", veabxSubgraph.url);
    console.log("fetchDataFromSubgraph - query:", query);
    console.log("fetchDataFromSubgraph - variables:", variables);
    const data = await fetchFromSubgraph(veabxSubgraph, {
      query,
      variables,
      requestId: "useVeABXLocks"
    });
    console.log("fetchDataFromSubgraph - response data:", data);
    return data;
  } catch (error) {
    console.error("Failed to fetch veABX data:", error);
    return null;
  }
}
export function useVeABXUserLocks(owner, enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["veabx-user-locks", owner?.toLowerCase(), chainId],
    queryFn: async () => {
      if (!owner) return [];
      const data = await fetchDataFromSubgraph(
        GET_USER_LOCKS_QUERY,
        { owner: owner.toLowerCase() },
        chainId
      );
      return data?.veABXLocks || [];
    },
    enabled: enabled && !!owner,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useVeABXGlobals(enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["veabx-globals", chainId],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(
        GET_VEABX_GLOBALS_QUERY,
        {},
        chainId
      );
      return data?.veABXGlobals || [];
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
export function useVeABXLock(lockId, enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["veabx-lock", lockId, chainId],
    queryFn: async () => {
      if (!lockId) return null;
      const data = await fetchDataFromSubgraph(
        GET_SINGLE_LOCK_QUERY,
        { id: lockId },
        chainId
      );
      return data?.veABXLock || null;
    },
    enabled: enabled && !!lockId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useManagedVeABXRelays(enabled = true, chainId = UniverseChainId.Mainnet) {
  return useQuery({
    queryKey: ["veabx-managed-relays", chainId],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(
        GET_MANAGED_RELAYS_QUERY,
        {},
        chainId
      );
      return data?.veABXLocks || [];
    },
    enabled,
    refetchInterval: 6e4,
    staleTime: 3e4
  });
}
